do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-002","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"y1","relation":"works","key":{"id":987101001},"before":{"id":987101001,"title":"It Ends With Us","cover_id":null,"author_id":987301001,"work_type":null,"source_type":"open_library","open_library_id":"OL18020194W","first_publish_year":2012,"native_identity_key":"nlscale:fixture002:681"},"after":{"id":987101001,"title":"It Ends With Us","cover_id":null,"author_id":987301001,"work_type":null,"source_type":"open_library","open_library_id":"OL18020194W","first_publish_year":2016,"native_identity_key":"nlscale:fixture002:681"}},{"ref":"e1","relation":"editions","key":{"open_library_edition_id":"OL35256642M"},"before":null,"after":{"work_id":987101001,"open_library_edition_id":"OL35256642M","isbn_13":"9789401910552","isbn_10":null,"language":"dut","publisher":"Uitgeverij Zomer & Keuning / Z&K","title":"Nooit meer","id":987201014,"publish_date":null,"cover_id":12916672}},{"ref":"d1","relation":"catalog_work_descriptions","key":{"work_id":987101001,"language":"nl"},"before":null,"after":{"work_id":987101001,"language":"nl","bound_author_id":987301001,"text":"Lily heeft in Boston een eigen bestaan opgebouwd en is een onderneming begonnen. Haar ontmoeting met neurochirurg Ryle lijkt een nieuwe toekomst te openen, maar zijn houding tegenover relaties roept vragen op. Tegelijk keren herinneringen terug aan Atlas, haar eerste liefde en een belangrijke figuur uit haar jeugd. Wanneer hij opnieuw verschijnt, moet Lily haar verleden en haar huidige keuzes tegenover elkaar plaatsen. De roman volgt hoe liefde ingewikkeld kan worden wanneer oude ervaringen blijven doorwerken.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.simonandschuster.co.uk/books/It-Ends-With-Us/Colleen-Hoover/9781471156267","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/