een coma en ontdekt dat aanrakingen hem onverklaarbare beelden opleveren. Wat hij daarin ziet, verandert zijn verhouding tot andere mensen en tot zijn eigen toekomst. Zijn vermogen brengt hem in aanraking met een moordonderzoek en met de opkomst van een politicus. Niet alles wordt duidelijk en sommige informatie blijft ontoegankelijk. Johnny moet bepalen hoeveel verantwoordelijkheid hij draagt voor gebeurtenissen die hij meent te voorzien, maar die anderen niet op dezelfde manier kunnen begrijpen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL81630W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p239646126"],"checked_at":"2026-11-02T16:27:00.000Z","reference":"work:227","note":"Exact Dutch KB original The dead zone1979. Dodelijk dilemma is a translated title of this Work."},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL81630W","https://data.bibliotheken.nl/id/nbt/p239646126"],"review":"content-review-017.json"},{"type":"cover_front_review","cover_id":14653577,"sha256":"ffed5234554ada12d077354e3b5dfbf906cf820bab01591f0acc40a38ae335a2","reference":"cover-semantic-review-002.json","limitation":"Front title/author and bound exact source edition; no visible barcode assertion."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T16:27:00.000Z","review_batch":"nl-scale-20261102-002"}},{"ref":"m4","relation":"catalog_edition_metadata","key":{"edition_id":"@e4"},"before":null,"after":{"edition_id":"@e4","work_id":987101004,"bound_author_id":928300049,"bound_title":"Dodelijk dilemma","bound_language":"dut","bound_isbn13":"9789024544974","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/14653577-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/14653577-M.jpg?default=false","evidence_url":"http