a256":"d2a52a7ced7f9cfa35be21d83bc4d7bff0090fc7b172fd26646cc7b6823ea83c","reference":"cover-semantic-review-002.json","limitation":"Front title/author and bound exact source edition; no visible barcode assertion."}],"review_status":"approved","reviewed_at":"2026-11-02T16:27:00.000Z","review_batch":"nl-scale-20261102-002"}},{"ref":"e6","relation":"editions","key":{"open_library_edition_id":"OL26453010M"},"before":null,"after":{"work_id":987101006,"open_library_edition_id":"OL26453010M","isbn_13":"9789057124389","isbn_10":null,"language":"dut","publisher":"Nieuwezijds / Nieuwezijds b.v.","title":"Sterfelijk zijn","id":987201019,"publish_date":null,"cover_id":8178872}},{"ref":"d6","relation":"catalog_work_descriptions","key":{"work_id":987101006,"language":"nl"},"before":null,"after":{"work_id":987101006,"language":"nl","bound_author_id":987301004,"text":"Atul Gawande onderzoekt hoe de geneeskunde omgaat met ouder worden, kwetsbaarheid en het einde van het leven. Hij verbindt ervaringen uit de zorg met persoonlijke verhalen en vragen over wat voor mensen zelf belangrijk is. Daarbij stelt hij de nadruk op langer overleven tegenover aandacht voor welzijn en eigen keuzes. Het boek verkent hoe gesprekken over grenzen en wensen ruimte kunnen krijgen, ook wanneer medische behandeling de onzekerheid niet kan wegnemen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL17079567W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p383945747"],"checked_at":"2026-11-02T16:27:00.000Z","reference":"work:3672","note":"Exact KB original Being mortal2014 and author agree. Non-fiction remains outside automatic taste-test classification."},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL17079567W","https://data.bibliotheken.nl/id/nbt/p383945747"],"review":"content-review-017.json"},{"type":"cover_front_review