erson/the-big-bad-wolf/9780316743846/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p317909479"],"checked_at":"2026-11-02T16:27:00.000Z","reference":"work:557","note":"Original author/publisher and KB original agree on2003, not current2001. Full Alex Cross novel, not another book called Wolf."},{"type":"original_substantive_source_review","sources":["https://www.jamespatterson.com/titles/james-patterson/the-big-bad-wolf/9780316743846/","https://openlibrary.org/works/OL167179W","https://data.bibliotheken.nl/id/nbt/p317909479"],"review":"content-review-018.json"},{"type":"cover_front_review","cover_id":13536475,"sha256":"7f19cb6f06f8221cdd64caaa7660791123b0a88c18a390690e690a17994cdef3","reference":"cover-semantic-review-002.json","limitation":"Front title/author and bound exact source edition; no visible barcode assertion."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T16:27:00.000Z","review_batch":"nl-scale-20261102-002"}},{"ref":"m13","relation":"catalog_edition_metadata","key":{"edition_id":"@e13"},"before":null,"after":{"edition_id":"@e13","work_id":987101013,"bound_author_id":946300342,"bound_title":"Het uur van de wolf","bound_language":"dut","bound_isbn13":"9789046113417","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/13536475-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/13536475-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p317909479","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p317909479"],"checked_at":"2026-11-02T16:27:00.000Z","reference":"work:557","note":"Original author/publisher and KB original agree on2003, not current2001. Full Alex Cross novel, not another book called Wolf."},{"type":"original_substantive_source_review","sources":["https://www.jamespatterson.com/titles/james-patterson/the-big-bad-w